    "Apply" 
    "For technical or economic immigrants to Canada, the Canadian Immigration, Refugee and Citizenship Commission (IRCC) formally requires candidates to submit their Canadian academic equivalence or educational credit assessment (ECA) in their immigration application. Under the new immigration policy, fast entry and educational attainments have a higher value. Main applicants, including their spouses, can receive their total comprehensive ranking system (CSR) score. For U.S. H-1B visas, U.S. Citizenship and Immigration Services requires a bachelor's degree or higher degree or its equivalent evaluation report." 
