    "WSE 2018-2019 STRATEGIC PLAN" 
    "INTRODUCTION" 
    "Word Service Education (WSE) was incorporated in 2013. In the relatively short span of time from incorporation until now, our association has grown and contributed to our field at an impressive pace. Official membership has topped 200, we represent over 15 countries and have held three successful international conferences. We have provided resources and training to people who do the important work of international credential assessment" 
    "In order to meet the needs of our membership and continue to contribute to the world community by doing work that supports the movement of people across borders for educational, commercial and personal reasons, we need to plan. In September 2017 we completed a comprehensive process that resulted in this plan that will set the strategic direction of the organization in the years ahead" 
    "PROCESS" 
    "The strategic planning process included the following" 
    "Stakeholder input and information gathering" 
    "In order to understand the needs and goals of the association members and to review the association’s position in the international education environment, we collected data. We surveyed the WSE membership, all current WSE leaders, and all candidates for elected WSE positions. We gathered data on the current state of our association, on our external environment, and the international education community in which our members do their work" 
    "Analysis of issues and trends by association leaders" 
    "WSE leaders and leader candidates met for an all-day retreat as part of the third annual meeting in Rome. At the meeting we reviewed our mission and operational principles, financial condition and accomplishments. Leaders reviewed member survey results, committee priorities and issues facing the association. An environmental scan and SWOT (strengths, weaknesses, opportunities and threats) analysis provided a context for our future direction" 
    "AREAS OF FOCUS" 
    "After sifting through all the data, discussion and analysis, the group identified three major areas of focus. These, along with overarching goals, are" 
    "By the end of 2019, have in place the Foundation Certificate and at least three subject-specific certificates to meet the needs of WSE members at all levels" 
    "Professional Development" 
    "By the end of 2019, offer a comprehensive package of professional development programs that supports WSE members at all levels" 
    "Finances" 
    "By the end of 2019, support the continued development of the Certificate Program, professional development and other programs, and maintain fiscal responsibility through a variety of revenue streams such as the annual conference, sponsorship, and program fees" 
