    "Perfect Storm:" 
    "There’s been a lot of genuine excitement around using the blockchain within higher education (and beyond) because the promise is immense. The promise is that it will enable students to hold and share their own official records directly with others in a manner that is safe, tamper-proof, and trusted. We’re talking about degrees, transcripts, certifications, badges … everything. That is a really big deal." 
    "Before we dive into details that technology, let’s cover some background. Even though schools moved from sheepskin to digital records a while ago, schools are still acting as the sole record keepers for student information. If a student wants to access or share their official records, they have to engage in a slow, complicated, and often expensive process. And so, for the most part, those records aren’t used much after graduation, nor built upon." 
    "Additionally, education is changing. Online learning and competency-based programs are rising in popularity. And this is magnified by a rapidly growing number of accredited education providers that expand far beyond traditional schools. This is causing a proliferation of educational claims that are hard to manage and it raises many new questions, both in terms of policy and technology. And what I hope to explain today is how a new technical infrastructure has emerged that enables students to be part of the solution by acting as their own lifelong registrar." 
    "Let’s start by looking at an example. A little over a year ago, the MIT Media Lab started an experiment for issuing some alumni digital certificates that could be validated using the Bitcoin blockchain. I say “experiment,” because it wasn’t ready to be safely released to the public, but it did illustrate how to use the blockchain as a notary for issuing certificates and verifying their authenticity." 
    "The image above shows that verification process taking place, which involves checking MIT’s signature, checking that nothing has changed in the certificate itself, and checking that the certificate hasn’t expired or been revoked. Once all that checks out, which just takes a second, a verified status is displayed." 
    "We’ve all heard funny stories of kids attempting to text photos of their official grades during the admissions process, but MIT’s prototype demonstrated how this new technology could actually secure that type of direct interaction for sharing official records." 
    "Let’s take a closer look at that prototype. The bottom of this slide represents the global blockchain database, which is basically a timeline of transactions. It is constituted by blocks of transactions that form one continuous chain. A blockchain. And because each new block builds upon the previous block, the entire chain is immutable. This is why it’s often referred to as a secure anchor of trust, because no government or private company can edit its history. And the schematic on top shows the core concept for logging certificate transactions." 
    "The blockchain itself is simply a ledger of transactions. In the case of money, it is recording financial transactions: who sent it, who received it, and how much. That pattern makes it ideally suited to record academic credentialing as well, because it records the same basic things: who issued it, who received it, and a one-way hash of the content that can later be used for verification. An academic achievement is simply another kind of value." 
    "The idea was clear, but this prototype had barriers preventing much use in the real world. For instance, it didn’t take into account how to efficiently issue thousands of certificates at the same time in a manner that was computationally efficient or cost effective. So, we began a year long collaboration to expand the concept and implementation into a complete toolkit of open-source components that any developer, school, or vendor could use." 
    "And I should point out, that this codebase is already being used by MIT and others, so the future is here. It’s not two years away." 
    "Now, let’s take a look at how all these components can work together in the real world. This diagram is organized into three lanes: one for a school, one for a student, and one for employers or anyone else that needs to verify authenticity." 
    "The process starts with the mobile app, which handles all of the crypto key-management stuff in the background. And just as you might add friends within a new app, the student simply adds their school. This sends the school their name, email, and public key which establishes a strong connection between them. Once that’s setup, the school can begin issuing that person certificates." 
    "When a certificate is issued, a record of the transaction goes onto the blockchain. And the student can then hold their official certificate within their mobile app. The school still has an official copy, but now the student does as well." 
    "Let’s say that student later wants to apply for a job. They apply through an employer’s HR system and they paste a link to their certificate. The HR system uses an independent blockchain verification service to verify any claims that are made. And it’s by using an independent verification service, as oppose to the one built into the certificate, that sidesteps any attempts at faking a blockchain certificate." 
    "That’s it. No school, vendor, or institution has to be consulted at any point during the verification process. The student has a convenient way to use their academic credentials, and employers have an immediate way to view and verify those claims. And perhaps more profoundly, the world has an entirely new infrastructure of trust for the 21st century." 
    "So let’s talk a little more about that infrastructure. The Bitcoin blockchain persists as a distributed network all over the world, just like the Internet. It’s replicated across thousands of computers, so it can’t be easily taken down. If institutions disappear, or even if entire governments collapse, people with blockchain-based certificates can still prove their education and what they have achieved. In essence, they can prove who they are. And the current refugee crisis highlights the relevance of this breakthrough. People need a more reliable ways to operate as self-sovereign individuals." 
    "In my experience, once schools grasp the magnitude of this technology, they want to get practical. How can they use it? How easy is it to get started?" 
    "If you’re a developer, the code and instructions for building are available today at blockcerts.org. If you’re school that wants a convenient product, we’ll be launching a commercial app for Registrars this January, which provides a graphical interface for issuing and tracking the use of certificates. This commercial product will also serve as a model to other vendors, for how they can use the Blockcerts toolkit to build out their own solutions." 
    "And, I want to show you a preview of the product, because I think that seeing a friendly user interface can also help to clarify many of these concepts." 
    "This particular view is part of the process for issuing a certificate template to an entire cohort of students. It’s kind of like an email campaign. At this point, the certificate on the right has been defined, the recipient list can be selected, the date/time of issuance can be scheduled, and the email notification can be customized as well. Once this goes out, the transaction gets registered on the the blockchain and the certificate appears for students in their mobile app. Image for post" 
    "That’s what we’re looking at now above. Certificates are organized by school, which could include corporate training, alternative schools or any type of education provider. Individual certificates can be viewed and ultimately shared publicly online or privately with a third party. While issuing and verification happens via the bitcoin network, the certificate can also be displayed on the web, which generates the normal kinds of web analytics, like clicks and views." 
    "So, coming back to the school’s view above, we’re now looking at a dashboard for the Advanced Robotics certificate where activity data is visualized. This provides schools a whole new layer of analytics that have never existed before. And these analytics could greatly be expanded should schools utilize some known taxonomy or credential registry. That data could be built into each certificate automatically resulting in more detailed analytics." 
    "This is obviously beneficial for everyone involved. First, it gives graduates a useful tool that directly contributes to their economic advancement. And by using a school’s branded certificates, it creates a daily reminder of the school in the mind of graduates and in the mind of others who are viewing certificates. So certificates become a type of marketing. And more importantly, the school and student maintain a connection that’s alive, far after graduation. And that ongoing connection has a lot of potential." 
    "So, hopefully that’s enough to kick off good conversation!" 
    "The presentation was followed by 45 minutes of great questions, most revolving around logistics like lost certificates, the longevity of the Bitcoin blockchain, and how employers adopt the verification service. Overall, a great discussion and enthusiasm for this direction." 
