    "Applicant Agreement and Consent - General Application" 
    "I hereby request an assessment of the enclosed credentials. I certify that all statements and materials filed in support are true and genuine. I understand that in some cases, the Degree Assessment Education (DAE) of the WSE of Continuing Studies may ask to review my original documents and ask for additional documents and/or information. In addition, I acknowledge that documents submitted will not be returned to me and that all fees are final and non-refundable. I will notify WSE in writing of any change to my personal information or to my decision to designate a third party to represent me during the WSE application process." 
    "I hereby authorize WSE to contact the institution(s) that issued my academic documents for the purposes of" 
    "Verifying document authenticity" 
    "Requesting information to assist in the assessment" 
    "I furthermore authorize and direct the said institution(s) to release to WSE any information contained in their respective files concerning my educational records and any other information that may be relevant to my application for an Degree Assessment Education. I agree that I will be responsible for any applicable fees or verification costs required by my former institution(s)." 
    "I authorize that my date of birth (DOB) be used for identification purposes on my Degree Assessment Education (DAE) Report. I understand that my personal information is being collected for the purpose of obtaining an DAE Report. I agree that WSE may retain my personal non-financial information for ten years from the date of my application, and that it may retain this information indefinitely if WSE determines that my documents are not authentic. I understand that measures will be taken in the event that my documents are determined to be false, including the nullification of any assessment reports already issued and notification to other credential assessment agencies and related government officials." 
    "I hereby release the WSE, its agents, and any person or entity that provides information in accordance with this consent, from any and all actions, claims and demands for damages, loss, expense or injury, howsoever arising, which may hereafter be sustained by me as a result of the provision, collection, use or disclosure of information as set out above." 
    "The WSE respects your privacy. Personal information you provide to the University is collected pursuant to section 2(14) of the WSE Act, 1971. The information you provide on this form will be used in assessing your request. At all times it will be protected in accordance with the Freedom of Information and Protection of Privacy Act. If you have any questions about WSE privacy measures, please contact WSE" 
