    "IPG: Canadian Pharmacy Skills (CPS) 1 Application" 
    "READ INSTRUCTIONS" 
    "Meet the program’s minimum requirements" 
    "Complete the online IPG Application" 
    "Prepare and upload all required documents to the online IPG Application" 
    "Pay the full tuition through the online IPG Application. Payment is accepted by Visa, Mastercard, and AMEX only. We do not accept cash, debit, or personal cheques. If you need to pay by Canadian Bank Draft/money order (payable to the WSE) please complete and save your online application and then bring or mail the Canadian Bank Draft/money order to the following address:" 
    "IPG Program" 
    "Toronto, Ontario" 
    "Application Approval Process" 
    "A receipt and Confirmation of Registration and Acceptance letter will be emailed once the online IPG Application is complete and the tuition is paid in full." 
    "The fees associated with the application are as follows, and will be charged following completion of this application:" 
    "Learners who require a letter to apply for a student visa can use the emailed Confirmation of Registration and Acceptance." 
    "Application fee, non-refundable" 
    "CPS1 Semester 1 tuition fee" 
    "Your application will be reviewed to ensure that the minimum requirements have been met. If they have not been met, a team member will reach out to you." 
    "Once your application has been approved or denied you will be contacted by email." 
    "IPG Program Document Requirements" 
    "Requirements:" 
    "A copy of the letter stating that you have successfully completed the Pharmacy Examining Board of Canada (PEBC) Evaluating Examination." 
    "Scan and save file as firstname_lastname-PEBC results" 
    "A copy of your valid Objective English Language Proficiency test score that meets the minimum requirement. You can find a summary of minimum requirements on the" 
    "OCP website" 
    "If you are a native English speaker you may request a Non-Objective Evidence of Language Proficiency from the Ontario College of Pharmacists (OCP). In order to do so, you must have a file open with OCP in order for them to review your documents. You can find additional information on their website," 
    "here" 
    "Scan and save file as firstname_lastname-Language Proficiency" 
    "A recent résumé with your current contact information; including address, email, phone number, and a summary of your education and career history in PDF format." 
    "Scan and save resume file as firstname_lastname-Resume" 
    "Visas and Study Permits" 
    "Visa Requirements:" 
    "Most foreign nationals require a Study Permit for the duration of the IPG Program. For more information on a Study Permit application, please visit" 
    "Immigration, Refugees and Citizenship Canada (IRCC)" 
    "Please note:" 
    "It is your responsibility to arrange the correct visas and permits in order to study in Canada by following the application procedures set by" 
    "IRCC" 
    "in your country." 
    "In order to acquire a Study Permit you will need to submit your Confirmation of Registration and Acceptance letter. This will automatically be emailed to you once you complete the online IPG Application and the tuition is paid in full." 
    "We advise you apply well in advance of the admission deadline date to allow for sufficient processing time. Immigration, Refugees and Citizenship Canada (IRCC) provides information about" 
    "estimated processing times" 
    "The visa must be valid for the entire length of the IPG program." 
    "To view our most frequently asked questions, please visit our Help Centre." 
