    "Explanation of Confirmation of Registration and Acceptance" 
    "The Confirmation of Registration and Acceptance document is issued for the purposes of obtaining a visa to study in Canada. It is not confirmation that you have been admitted into the IPG program. To be admitted into the program you must meet the minimum requirements." 
    "Upon submission of this online application, your application will be reviewed to confirm that you meet minimum requirements. You will be contacted once your application is approved or denied. If you do not meet minimum requirements, your tuition fee will be refunded to you." 
    "Please confirm that you understand the purpose of the Confirmation of Registration and Acceptance letter and that admission into the IPG Program is only confirmed once your application has been approved." 
