    "Data update service description" 
    "Data update should select different update types according to your current actual situation. Currently WSE only provides the above two data update methods. For specific data update instructions, please see the following:" 
    "1. Education promotion: When you have already submitted an application in WSE, and the application education you submitted does not match your current education, you want to update the latest education information, then you can choose the data update method of \"education improvement\"" 
    "2. Modification of current academic information: If you have just applied for WSE recently, but your information is submitted incorrectly due to negligence, and the information on your assessment report is also wrong, you can submit relevant information to update your data" 
    "Both are suitable for different application requirements, please determine your data update requirements before choosing. You can decide which data update method to use according to your different needs" 
