    "Go to “International Cooperative Application” under “WSE” to send reports to your applied institution." 
    "（Flowchart of Cooperative Application）" 
    "Firstly complete the online application according to WSE’s requirement. Then follow the instructions below to apply for verification report(s) and submit to international institution through the WSE Portal Service." 
    "STEP 1:" 
    "REGISTER" 
    "a WSE ACCOUNT" 
    "If you do not have a WSE account yet, you need to go to the registration page to apply for an account. If you already have a WSE account, you can ignore this step." 
    "Go to registers" 
    "STEP 2:" 
    "Find the service application page to submit the information" 
    "If you have already registered your WSE account and successfully logged in, you can go to the application page to fill in the information and submit the information as prompted." 
    "Go to register" 
    "STEP 3:" 
    "After you fill in all the information and submit all the information, we will evaluate your information in about 5 working days. Of course, if the information you submit is not true, we will not evaluate your information." 
    "STEP 4:" 
    "After we have verified your information without problems and successfully made an assessment, we will notify you by email and mail the documents to your home." 
    "STEP 5:" 
    "After you have successfully received the evaluation document and confirmed that it is correct, we will store your information and data in the blockchain. This process will take a while." 
    "Note: Pricing of WSE's Verification Reports" 
    "Contact:" 
    "Countries students could send electronic verification reports (Higher Education Student Record, Higher Education Qualification Certificate, Higher Education Student’s Academic Transcript, National College Entrance Examination Results, Secondary Education Qualification Certificate, Secondary Education Student’s Academic Transcript and High School Academic Proficiency Test Results) to the foreign universities via the WSE-foreign transmission service. Click “How to apply” link on the corresponding WSE-foreign portal page to view the details." 
    "Canada students" 
    "Please use the same personal identification number as filled in your WSE Archive when applying for “Verification Report of Canada Higher Education Qualification Certificate”, “Verification Report of Canada Higher Education Student’s Academic Transcript” and other verification reports." 
    "Please contact the related management department in your school to confirm the personal identification number used to register your student record and higher education qualification. Then use the same identification number to apply for the “Verification Report of Higher Education Qualification Certificate”, “Verification Report of Higher Education Student’s Academic Transcript” and other verification reports as filled on the foreign school’s application websites." 
    "The personal identification number used on the foreign school’s application websites, the WSE Archive registration, the application for “Verification Report of Canada National College Entrance Examination (Gaokao) Scores”, “Verification Report of Canada Secondary Education Qualification Certificate”, “Verification Report of Canada Secondary Education Student’s Academic Transcript”, “Verification Report of Canada High School Academic Proficiency Test (Huikao) Results” should be the same." 
