    "What is Records Keeper?" 
    "A PROTOCOL FOR INTELLIGENT RECORD KEEPING & DATA SECURITY THROUGH BLOCKCHAIN" 
    "Legally Acceptable & Verifiable Records" 
    "Records Keeper is built for anyone who is looking to make their data more trustworthy through Blockchain-based records. Through Blockchain-verified records & information, it is integrity can be checked.." 
    "Immutable & Unmodifiable Records" 
    "Once a record has been published, no one, not even the owner can change the records, only a chronological trail of modified records can be seen by anyone globally. Adding to the trust in the data." 
    "Open, Public & Transparent" 
    "Open-source Blockchain maintains a ledger of records in a simple key-value pair. Just query using a key or tx id & verify the record. Check its trail of version & when they got published." 
    "Start Trusting Your Data With Records keeper Today" 
    "With tools to make every part of your day-to-day work easy, our support team is excited to help you to get started with onboarding the existing scattered data to well-structured easy to find records in safe domestic servers with end-to-end encryption and bank-grade security. Security, Privacy & Transparency, all come together in one place." 
    "GET STARTED" 
    "Make Data Verifiable without Trusted Third Party" 
    "WSE allows you to create verifiable & immutable records of any types of data that are not possible in traditional technologies like MySQL, Oracle, MSSQL, etc." 
    "This can also be seen as a tool to generate a Proof-of-Existence, Proof-of-Authenticity & Proof-of-Integrity of a file, record, document, certificate, degree on Blockchain." 
