 	"Yes, you can order a copy of the report for up to 5 years from the date the report is first published. After five years, applicants will no longer be able to order copies of their reports. You can apply for additional copies through \"<a>Application Copy</a>\"" 
    "No, you can submit evaluation files or education file storage files provided by relevant authorities to us through \"<a href=\"\">Special Service</a> \", we accept these files and provide the same service" 
    "Members of ACESC issue <a href=\"#\">assessment reports for general purposes</a> to outline expert, non-binding opinions on the assessment of academic credentials issued outside Canada. These reports are widely used by competent recognition authorities in Canada—i.e., educational institutions, professional regulatory authorities and associations, immigration authorities, and employers—that require assistance with document authentication and comparability procedures." 
    "Get more <a href=\"/docs/EN_2018-06_ACESC_background_information.pdf\">background information on ACESC</a> and consult CAED’s Web site to get an <a href=\"https://www.CAED.ca/1398/an_overview_of_the_lisbon_recognition_convention.canada\">overview of the Lisbon Recognition Convention (LRC)</a>." 
    "The <a href=\"#\">Pan-Canadian Quality Assurance Framework for the Assessment of International Academic Credentials</a> (QAF) was developed by CAED in collaboration with ACESC, and the policies and procedures of all member organizations comply with QAF’s principles and recommendations. ACESC also supported the development of CAED’s Assessor Portal— <a href=\"#\">Assessor.CAED.ca</a> —which features tools and resources used by the pan-Canadian community of academic credential assessors. ACESC members undergo a rigorous annual self-assessment and peer-review process to examine a number of criteria. Membership is conditional on continued compliance with the Terms of References." 
    "Get more information on the ACESC <a href=\"/docs/EN_Terms_of_Reference_as_of_July_9_2018.pdf\">Terms of Reference</a>, <a href=\"/docs/Alliance_Membership_application.pdf\">Membership Application Form</a> , and <a href=\"/docs/Annual_self-assessment_form.pdf\">Annual Self-Assessment Form</a>." 
    "To contact the ACESC Secretariat, consult CAED’s <a href=\"#\">Web site.</a>" 
    "In the history of global education, 2020 will go down as the year the coronavirus pandemic savaged education systems worldwide, closed schools in 192 countries, and locked more than 90 percent of enrolled learners out of classrooms <a href=''>globally</a> . It will be remembered as a year of chaos, makeshift solutions, uncomfortable compromises, and, quite possibly, a few questionable decisions." 
    "Social distancing upended secondary school leaving examinations and university entrance tests worldwide, disrupting the admission of new students for upcoming academic terms. Because of differences in academic calendars and epidemic peak periods, not all countries have been affected equally. For instance, the one-month delay of China’s gaokao, the world’s largest university entrance exam, is unlikely to affect the admission prospects of the more than 10 million students expected to sit for the exam <a href=''>in July</a>." 
    "But other countries have been affected more severely. To name but a few examples, the British government in March canceled the GCSE, AS, and A level exams, originally scheduled to take place in June; while the West African Examinations Council <a href= ''>indefinitely suspended</a>the high-stakes West African Senior School Certificate Examination, the main secondary school leaving qualification in five countries, including Nigeria. In another example, the United States canceled the SAT <a href= ''>standardized tests</a>, required for admission by more than half of U.S. higher education institutions (HEIs), especially <a href= ''> prestigious universities</a>." 
    "What’s more, the suspension of selection criteria doesn’t necessarily make access to education more equitable. As noted by Angel Pérez, vice president for enrollment and student success at Trinity College, in the U.S. context, “when rich students have school counselors, test prep tutors, and independent education consultants to proactively provide solutions to the cancellations of SAT and ACT test dates, low-income students will have to scramble to find information and develop <a href=''>alternative plans</a>. … The <a href= ''>March SAT</a> is a prime example of the unequal access to testing and its disparate impact on communities. As large urban districts closed all schools and canceled SATs, some private schools held their March SAT.”" 
    "Such concerns about social fairness are echoed by U.K.-based education experts, many of whom maintain that predicted A level exam grades—currently slated to be used for admission in lieu of actual scores—disadvantage students from low-income households. Research has shown that predictive grades accurately reflect final exam grades <a href= ''>less than 20 percent of the time</a> , and may also underestimate the test performance of top students from disadvantaged social backgrounds. Put differently, high-performing students from low-income households may be—unintentionally or not—among the losers of the U.K.’s pandemic emergency response." 
    "There are also concerns that the suspension of competitive student selection mechanisms could alter the structure of university systems. The U.K. government, for instance, is considering imposing admission quotas to prevent top universities, now freed from the constraints of normal admissions standards, to compensate for dwindling international student numbers by “hoovering up” larger numbers of domestic students—a move that could jeopardize the financial viability of less <a href=''>prestigious institutions</a>." 
    "India’s University Grants Commission, meanwhile, has suggested the opposite. It proposed that universities hold <a href= ''>joint admissions examinations</a> to make it easier for students to apply to multiple institutions amid travel restrictions—a recommendation that could lead to a standardization of admissions procedures, similar to the unified admissions process that was recently developed in the field <a href= ''>of medicine</a>." 
    "As noted, the suspension of face-to-face instruction in most parts of the world has created pressures to promote and graduate students without examinations or other regular requirements. While the most common approach thus far has been to postpone exams, countries like <a href= ''>Norway</a> , <a href=''>Indonesia</a>, and France canceled examinations outright, opting to promote students based on criteria like average scores in school subjects “calculated from marks given for tests and homework <a href= ''>throughout the year</a>.” The International Baccalaureate (IB) is taking the unusual step of awarding the IB diploma based on “data analysis from previous exam sessions,” school performance data, and the external grading of coursework <a href= ''>provided by schools</a>." 
    "Meanwhile, universities in Canada, <a href= ''>the U.S</a>., and other countries are suspending standard grading practices for the current term, assessing students on a pass/fail basis, or adopting other flexible approaches, such as allowing students to choose <a href= ''>credit/no credit options</a>. There is an equity dimension to these changes. When coursework and exams are moved online, low-income households are disadvantaged, since they disproportionately lack access to computer devices or internet connections, particularly in developing countries. Compared with their richer peers, these students are more likely to live in environments unsuitable to learning, they may have to share devices with family members, and so on." 
    "Considering these realities, student organizations in the Philippines and elsewhere have demanded that universities promote students with lenience rather than continue classes online. Student unions in several African countries urged universities to stop online exams amid digital divides and called for the boycott of “elitist” <a href= ''>remote learning solutions</a> . While distance education can help expand <a href= ''>access to education</a> in overburdened education systems with capacity shortages, shifting learning online in its entirety has severe social ramifications in countries with wide wealth disparities." 
    "However, there are other issues to consider. It’s inevitable that some will view switching to pass/fail grading scales or graduating students without exams as steps that penalize high-achieving students, or that are unfair to student cohorts of other years. As one U.S. student put it, the “pass/fail system is a disgrace to students who have worked hard for their A’s. For me, this is my best semester, and the pass/fail system takes away my GPA, which I need for internships and many other <a href= ''>career opportunities</a> .” There are various potentially negative implications for students down the road—from limiting <a href= ''>transfer credit options</a> to curtailing admission prospects because “their transcripts will be looked upon less favorably when they apply to graduate or <a href= ''>professional school</a> .” In the extreme, in countries that emphasize final examinations for the awarding of degrees, qualifications may be tarnished as “easy degrees.”" 
    "The compromises necessitated by the crisis are manifold. Consider that the U.S. waived examination and practice requirements to issue temporary emergency licenses to <a href= ''>physicians</a> , nurses, and other <a href= ''>health professionals</a> , while China waived licensing requirements for teachers and allowed them to start teaching without having passed required exams. Accreditation and licensing requirements for academic institutions were likewise suspended in different countries. The U.S. Department of Education, for instance, permitted accreditation agencies to extend accreditation terms, conduct virtual site visits, and bestow retroactive accreditation. According to the department’s guidelines, students graduating from a program with pending accreditation due to outstanding site visits are to be “considered to have graduated from <a href= ''>an accredited program</a> .”" 
    "Since it’s unclear how long the coronavirus pandemic will last and to what extent distance education will become more ubiquitous, it’s important that governments and quality assurance bodies adapt quickly to ensure that the new distance learning programs are of equal quality to regular programs on-site. This is not a trivial task. Recent studies from Australia, for instance, maintain that the current shift to distance education will have major negative impacts on <a href= ''>learning outcomes</a>. The rapid proliferation of distance learning courses raises other questions as well, such as the increased potential for cheating during online examinations" 
    "Further complicating international recruitment is rising anti-Asian sentiment, the racist <a href=\"\">scapegoating of Asians</a> for the spread of the virus, as well as increasing political tensions with China, the largest sending country of international students. It’s also possible that visa regulations will be tightened amid the crisis. Four U.S. senators have already warned that international students could take away “jobs that would otherwise go to unemployed Americans as our <a href=\"\">economy recovers</a> .” They urged the U.S. government to suspend the Optional Practical Training (OPT) program and the issuance of H-1B visas, both of which are major draws for international students from India, China, and elsewhere." 
    "But much will depend on the duration of the crisis. The longer it lasts, the more international students will change their plans. Longitudinal surveys of international students in different countries over <a href=\"\">the past few months</a> show a decreasing appetite for pursuing education abroad. Even if the U.S. could retain three quarters or more of its international student body over the next few semesters, the crisis could be existential for some institutions. The ripple effects for U.S. society at large could be destructive as well: According to NAFSA, three U.S. jobs are created or supported for every seven enrolled international student in the following sectors: higher education, accommodation, dining, retail, transportation, telecommunications and <a href=\"\">health insurance</a>”." 
    "The Australian government, for instance, currently plans to exempt international students from travel restrictions and allow them to return to Australia <a href=\"\">as early as July</a> —a scenario that seems out of reach in the U.S. at this point. Similarly, observers believe that New Zealand, a country which has effectively <a href=\"\">contained the pandemic</a>, will have “a real opportunity to become more desirable as a destination for <a href=\"\">foreign students</a>” because of the crisis." 
    "Equally disconcerting, if unsurprising, is the fact that 20 percent of prospective international students stated that they’re now likely to study in their home countries. This is a percentage that may well increase if the pandemic continues to drag on in the U.S. and other destination countries. Local surveys in India, cited in April by the <a href=\"\">Hindustan Times</a> , found that more than half of Indian students who had intended to study abroad planned to cancel those plans, while about a third of them sought to defer existing offers of acceptance by a year. Indian recruitment agents forecast increased competition over scarce domestic university seats this year as previously outbound students now find themselves seeking options at home." 
    "are detrimental in this context. While other countries are weighing options to attract more international students, including by expanding <a href=\"\">access to employment</a> , the Trump administration’s policies won’t help the U.S. hold on to its global share of the international student market, which has already declined by an estimated 6 percent since the beginning of <a href=\"\">the century</a> . Independent of possible visa restrictions, the current unemployment rate of close to <a href=\"\">15 percent</a> and the prospect of a protracted economic crisis mean that the U.S. will lose part of its sheen as a destination for students interested in employment and possibly immigration after graduation." 
    "Given the catastrophic economic outlook for countries globally, some observers have suggested that it will take international student mobility five years to recover from <a href=\"\">the pandemic</a>. While that forecast appears overly pessimistic, it’s all but certain that fewer students will head abroad for the foreseeable future as incomes and public scholarships dry up. Students from lower middle-income countries like India, Bangladesh, and Vietnam, all top sending countries of students to the U.S., may opt for less expensive study destinations that are closer to home, such as China, Malaysia, or South Korea. International branch campuses and transnational programs that allow students to obtain an international education without travel may become more popular." 
    "In sum, there’s reason for concern: 77 percent of HEIs surveyed by WES expect a downturn in international enrollments because of the crisis—a notable difference when compared to the Great Recession, which was accompanied by a significant <a href=\"\">uptick in enrollments</a> by domestic and international students alike. Most HEIs—64 percent—are extremely concerned that travel restrictions may impede international student mobility and 70 percent worry that new international students will not be able to get a visa. Sixty-four percent predict that HEIs will consequently increase “backyard recruitment” of foreign-educated students already in the U.S. to compensate for the loss." 
    "Given the uncertainties as to when the pandemic will be contained, growing numbers of institutions are shifting to online education beyond the summer. As of this writing, <a href=\"\">7 percent</a> of institutions have announced that they will deliver education online in the upcoming fall semester. Another 28 percent of HEIs, including major international host institutions like Columbia University and the University of Southern California, are still deciding or are considering other options, including blended learning. For international students unable to travel, distance learning will likely be more common: 52 percent of 234 U.S. HEIs polled in a <a href=\"\">recent survey</a> by the Institute of International Education stated that they would provide online options for international students in the fall." 
    "Some observers have suggested that the rapid global shift toward distance learning may provide HEIs with a golden opportunity to reach more students overseas with online programs. Former U.K. higher education minister Jo Johnson, for instance, thinks that British universities will be able to increase overseas enrollments from lower “income groups in Asia and Africa where young people do not necessarily want the full-fat, high-cost, three- to four-year program living in an <a href=\"\">English-speaking country</a>.”" 
    "However, while there’s certainly the potential to reach more students in untapped overseas markets with distance education programs, there are doubts about how popular online options will actually be for international students, especially among students already enrolled in degree programs. Fully 32 percent of international students surveyed by WES said that they would not continue their studies in online mode, while another 30 percent were undecided. This finding mirrors the sentiments of domestic students: 33 percent of prospective U.S. students polled in May said that they would “defer or cancel their fall semester if schools go <a href=\"\">totally online</a>.”" 
    "There are technical issues to consider as well. Several universities have reported difficulties delivering learning content to students in China because of internet censorship and the inaccessibility of popular <a href=\"\">online platforms</a>. What’s more, it will be difficult to offer online programs at the same price as full-fledged on-campus programs, so the revenues of major host institutions would be at risk either way if education were to be delivered wholly online on a prolonged basis." 
    "It remains an open question whether online education will help retain international students in the long run. While some students will certainly be put off by paying hefty fees for an international online education, some institutions and countries may stand to benefit. As one Canadian immigration policy analyst has noted, “international students who wish to eventually apply for Canadian immigration will want to capitalize on the opportunity to complete a portion of their studies in their countries of origin, while still being able to access the same benefits (the work permits) had they been required to physically study in Canada.… The cost to study in Canada will decline for them, since they will not have to incur additional living expenses at the outset of their <a href=\"\">Canadian education</a>.”" 
    "By and large, several of our survey findings are mirrored by those of other surveys. For example, <a href=\"\">69 percent</a> of 6,900 international students recently surveyed by U.K.-based education consultants IDP Connect stated that they still intend to begin their studies as planned. Most of them prefer to do so on campus and defer their start dates if necessary, while a sizable number of respondents were unwilling to continue studies in online mode, expressing concerns about quality and noting that it “ lacked international exposure.”" 
    "While these attitudes might change over time, as the crisis continues to unfold, <a href=\"\">32 percent</a> of prospective international students abroad surveyed by educations.com said they weren’t interested in continuing their studies in online mode. After surveying 22,000 international students, the Erasmus Student Network noted that while distance learning is an acceptable solution to an unprecedented problem ” … online classes are not a proper substitute for a physical mobility experience. Several problems were reported with the technical implementation of online courses, and while these can probably be worked around, the real ‘Erasmus experience’ is <a href=\"\">unlikely to be the same</a> ”. As QS summarized its most recent <a href=\"\">survey findings</a> , “international students may be deferred but they’re not deterred” from continuing their studies on campus should conditions permit." 
    "While it’s difficult to see international student mobility fully rebound under the current circumstances, it needs to be understood that global student mobility has grown consistently and reliably over the past three decades, crises like the Great Recession or the SARS epidemic notwithstanding. Consider that between 2000 and 2017, the number of mobile students enrolled in degree programs in other countries more than doubled, from 2 million to 5.3 million, according to the latest available UNESCO statistics. Looking forward, the number of tertiary students worldwide is estimated to rise from 251 million in 2020 to 594 million <a href=\"\"> by 2040</a>—making it all but certain that international student mobility will continue to increase, at least to some extent, in the long term." 
    "Past trends in the U.S., the most popular international study destination worldwide, show resilience to global crises as well. Aside from a brief period of stagnation in the early 2000s in the wake of the 9/11 terror attacks and the globally unpopular Iraq war, international student enrollments in the U.S. have been growing steadily, almost doubling between <a href=\"\">2006 and 2017</a> ." 
    "As of April 27th, 2020, the <a href=\"\">International Credential Evaluation Service (ICES)</a> has made the online application available again and will be open to receiving requests for evaluations both online and by mail. The Covid-19 pandemic will still certainly affect business operations including disruptions to mail services in many countries (see below). If you are unable to get your institution to provide educational documents and have already applied or are thinking of applying, we can still hold your application until such documents arrive." 
    "Here’s the update from <a href=\"\">Canada Post</a> , you can find specific information about disruptions in your <a href=\"\">country</a> here." 
    "Courier service is also impacted. Again, in some cases it has been suspended completely and in other cases there are severe delays. Also due to social distancing measures, there may be no signature requested at the time of delivery. For Domestic courier, please see the <a href=\"\">UPS services alerts</a>. For International courier, please see the <a href=\"\">DHL service alerts</a>. ICES is unable to provide estimated delivery times." 
    "Canada Post has suspended all mail services to Syria. Please see this notification of the <a href=\"\">OFAC trade embargo</a> for more information. If you apply and your return address is in Syria, we will not be able to offer any mail or courier service. In this case, please provide an alternate address for the delivery of your assessment." 
    "This is a transcript of the presentation given during <a href=\"\">Educause</a> at the Anaheim Convention Center on October 28, 2016." 
    "Hello everyone. My name is Chris Jagers. I’m the CEO of <a href=\"\">Learning Machine</a> , the software company that has been working with MIT over the last year to develop an open standard for blockchain certificates. I’ll be giving a short presentation about blockchain-based academic credentials, followed by a discussion with our panel and with all of you." 
    "This week, we’re excited to announce that this toolkit has been launched and is freely available at <a href=\"\">www.blockcerts.org</a>. This open standard is OBI compliant and includes libraries for creating, issuing, holding, viewing, and verifying blockchain credentials. There is no other public resource delivering this complete ecosystem. The website itself is a friendly introduction to the source code on Git, and it includes helpful articles that introduce the project, answers questions, and provides step-by-step guides." 
    "<a href=\"\">Analysis from 2011</a> summarizes less than one-quarter of all enrollment in higher education was at a four-year institution, and that percentage has been rapidly shrinking. Further, only half of those entrants into college are finishing. The rest are leaving with debt, no degree, and no other record with social value. Beyond the financial difficulty — for both students and schools — this trend is also creating new conceptions about what higher education should be. Rather than being a place for a select few to explore identity and possibly find a career, the model has flipped. Broad access is now considered a virtue and school is viewed increasingly as a pathway to a better job. And with so few attaining a degree, the idea of not finishing college has become the norm. The response to this mismatch between student expectations and academic options has been slow, not only because institutions are inherently slow to change, but also because the diverse growing numerical majority of non-traditional students has often been eclipsed by a lingering idealization of “traditional” students." 
    "First, there has been broad acknowledgment that time exposure to a subject doesn’t matter so much as actual skills achieved. In a <a href=\"\">2015 report</a>, the Carnegie Foundation put it this way:" 
    "<b>Students: </b> how can academic records become part of the educational experience and remain an ongoing resource to the student?" 
    "<b>Employers: </b> how can academic records become more useful for hiring?" 
    "<b>Schools: </b> how can they record more kinds of learning experiences without diluting what an education means and without losing common understandings of achievement?" 
    "I was fortunate to be invited to this year’s meeting about the <a href=\"\">Comprehensive Student Record</a> , hosted by the Lumina Foundation, which brought together leadership from schools from all over the U.S. to share their experiments for developing a more complete student record. Below are the dominant trends I observed, along with how securing records using the blockchain is directly aligned with strategic goals and serves all three stakeholder groups identified above." 
    "<a href=\"\">Steven Mintz</a>, Executive Director of the University of Texas System’s Institute for Transformational Learning, confirmed that that the University of Texas system has a 49% completion rate of students who finish with a degree, which mirrors national trends. In his beacon call about the state of education, <a href=\"\">Navigating the Perfect Storm</a> , he argues that without smaller units of academic achievement as options, many students simply leave with debt. Universities are responding by offering various kinds of certificate programs and online courses that create flexible pathways for working and remote students. ASU’s <a href=\"\">Global Freshman Academy</a> is a great example of these priorities put into practice." 
    "Stanford University Registrar <a href=\"\">Tom Black</a> shared their draft framework for organizing the 100+ certificate programs that are now being offered. It serves as a great example of how traditional universities can plan, organize, and prioritize their certificate programs." 
    "<b>Enriching digital documents: </b> Rather than simply making what was once a paper document digital (generally a PDF), building rich documents that are linked to course descriptions, coursework, projects, etc." 
    "<b>Adding a co-curricular transcript: </b> These include lists of experiences, achievements, and competencies that have been earned outside of the classroom. Of course, this project raises many important questions about academic “equivalence” and practical concerns over the complexity of an undertaking with a transnational scope." 
    "Any school genuinely interested in enabling a CSR/LLR should be investigating how to utilize the public blockchain as a notary. <a href=\"\">Blockcerts</a> provides the open-standard for interfacing with the blockchain and vendors like <a href=\"\">Learning Machine</a> are building commercial solutions that utilize the standard in supported, scalable, cost-effective ways. A summative academic or co-curricular transcript may also be part of that record, but those are just one more stop on a lifelong journey of learning. Image for post" 
